import { MeshStandardNodeMaterial, PlanarReflectionNode, Texture } from 'three/webgpu';
import { vec3, mix, uv, positionLocal, normalLocal, color, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Keep track of resources to clean up
  const timelines = [];
  const disposables = [];

  // STAGE BACKDROP (Satisfying the "STAGE, never void" rule)
  // 7x6 units at z = -2.5, transitioning from Surface (#0b0b10) to Ink (#16161d)
  const bgGeom = new THREE.PlaneGeometry(8, 7);
  disposables.push(bgGeom);

  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1,
    depthWrite: false
  });

  // Custom Node Material for Background Gradient
  const topColor = color(new THREE.Color('#16161d'));
  const bottomColor = color(new THREE.Color('#0b0b10'));
  bgMat.colorNode = mix(bottomColor, topColor, uv().y);

  const bgMesh = new THREE.Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // LOCAL LIGHTING
  // Adding localized lighting scheme so it renders beautifully according to "LIGHT like a product shot"
  const localRimLight = new THREE.DirectionalLight('#ff2a38', 1.2); // Signal Red Accent Rim
  localRimLight.position.set(4, 3, -1);
  group.add(localRimLight);

  const localKeyLight = new THREE.DirectionalLight('#e8ecf2', 0.8); // Paper White Key
  localKeyLight.position.set(-3, 4, 3);
  group.add(localKeyLight);

  // CARD CONTAINER OBJ (Positioned at local origin, scale as configured)
  const cardWidth = 2.4;
  const cardHeight = 3.6;
  const cardGeom = new THREE.PlaneGeometry(cardWidth, cardHeight, 32, 32);
  disposables.push(cardGeom);

  // Standard material leveraging nodes for rich metallic-brushed look + subtle grain
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    transparent: true,
    opacity: 0.98
  });

  // Base texture loader for image
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (tex) {
        tex.colorSpace = THREE.SRGBColorSpace;
        cardMat.colorNode = tex;
        cardMat.needsUpdate = true;
      }
    });
  } else {
    // Fallback engineered gradient if texture is missing
    const cardTop = color(new THREE.Color('#16161d'));
    const cardBottom = color(new THREE.Color('#0b0b10'));
    cardMat.colorNode = mix(cardBottom, cardTop, uv().y);
  }

  const cardMesh = new THREE.Mesh(cardGeom, cardMat);
  group.add(cardMesh);

  // Subtle Shadow Plane underneath
  const shadowGeom = new THREE.PlaneGeometry(cardWidth * 1.2, 0.4);
  disposables.push(shadowGeom);
  const shadowMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    roughness: 1.0,
    metalness: 0.0
  });
  const shadowMesh = new THREE.Mesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -(cardHeight / 2) - 0.1, -0.05);
  shadowMesh.rotation.x = -Math.PI * 0.4;
  group.add(shadowMesh);

  // Subtle Entrance Animation
  const enterTl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  cardMesh.scale.set(0.9, 0.9, 1);
  cardMesh.position.y = -0.2;

  enterTl.to(cardMesh.scale, { x: 1, y: 1, duration: 1.2 }, 0);
  enterTl.to(cardMesh.position, { y: 0, duration: 1.2 }, 0);
  timelines.push(enterTl);

  // CLEANUP METHOD
  group.userData = {
    handlers: {},
    cleanup: () => {
      timelines.forEach(tl => tl.kill());
      disposables.forEach(d => d.dispose());
      bgMat.dispose();
      cardMat.dispose();
      shadowMat.dispose();
    }
  };

  return group;
}
